function solve(s, numRows) {
  const n = s.length;
  if (numRows <= 1) return s;
  let out = '';
  for (let r = 0; r < numRows; r++) {
    let row = 0;
    let dir = 1;
    for (let i = 0; i < n; i++) {
      if (row === r) out += s[i];
      row += dir;
      if (row === numRows - 1) dir = -1;
      else if (row === 0) dir = 1;
    }
  }
  return out;
}

function solve(s, numRows) {
  const n = s.length;
  if (numRows <= 1 || numRows >= n) return s;
  const cycle = 2 * numRows - 2;
  let out = '';
  for (let r = 0; r < numRows; r++) {
    for (let i = r; i < n; i += cycle) {
      out += s[i];
      if (r !== 0 && r !== numRows - 1) {
        const diag = i + cycle - 2 * r;
        if (diag > i && diag < n) out += s[diag];
      }
    }
  }
  return out;
}
